use libgems::tiny_skia::{self, PixmapMut, PixmapRef, PremultipliedColorU8};

/// This function was generated by claude.
///
/// Copies a `w x h` rectangle from `src` at (sx, sy) into `dst` at (dx, dy),
/// alpha-blending manually (premultiplied "over"). Clips automatically to
/// both bitmaps' bounds -- out-of-range offsets/sizes just get truncated.
#[inline]
pub fn tiny_blit_blend(
    dst: &mut PixmapMut,
    src: PixmapRef,
    sx: i32,
    sy: i32,
    w: i32,
    h: i32,
    dx: i32,
    dy: i32,
) {
    let (src_w, src_h) = (src.width() as i32, src.height() as i32);
    let (dst_w, dst_h) = (dst.width() as i32, dst.height() as i32);

    // Valid column/row ranges (relative to sx/sy) that exist in *both* bitmaps.
    let col_from = 0.max(-sx).max(-dx);
    let col_to = w.min(src_w - sx).min(dst_w - dx);
    let row_from = 0.max(-sy).max(-dy);
    let row_to = h.min(src_h - sy).min(dst_h - dy);

    if col_from >= col_to || row_from >= row_to {
        return;
    }

    let src_pixels = src.pixels();
    let dst_pixels = dst.pixels_mut();

    for row in row_from..row_to {
        let s_row_base = ((sy + row) * src_w) as usize;
        let d_row_base = ((dy + row) * dst_w) as usize;

        for col in col_from..col_to {
            let s_idx = s_row_base + (sx + col) as usize;
            let d_idx = d_row_base + (dx + col) as usize;

            let s = src_pixels[s_idx];
            let sa = s.alpha();

            if sa == 0 {
                continue; // fully transparent source: leave dst untouched
            }
            if sa == 255 {
                dst_pixels[d_idx] = s; // fully opaque source: plain copy
                continue;
            }

            let d = dst_pixels[d_idx];
            let inv_a = 255 - sa as u32;

            let r = s.red() as u32 + div255(d.red() as u32 * inv_a);
            let g = s.green() as u32 + div255(d.green() as u32 * inv_a);
            let b = s.blue() as u32 + div255(d.blue() as u32 * inv_a);
            let a = (sa as u32 + div255(d.alpha() as u32 * inv_a)).min(255);

            // Clamp r/g/b to a to guard the premultiplied invariant against
            // any rounding edge case.
            let r = r.min(a) as u8;
            let g = g.min(a) as u8;
            let b = b.min(a) as u8;
            let a = a as u8;

            dst_pixels[d_idx] =
                unsafe { PremultipliedColorU8::from_rgba(r, g, b, a).unwrap_unchecked() };
        }
    }
}

/// Fast, exact integer division by 255 for values up to 255*255.
/// Equivalent to (x + 1 + (x >> 8)) >> 8, a well-known trick that matches
/// x / 255 exactly for 0 <= x <= 255*255.
#[inline(always)]
fn div255(x: u32) -> u32 {
    (x + 1 + (x >> 8)) >> 8
}

pub fn blend_pixel(src: &PremultipliedColorU8, dst: &mut tiny_skia::PremultipliedColorU8) {
    let sa = src.alpha();
    if sa == 0 {
        return; // fully transparent: leave dst untouched
    }
    if sa == 255 {
        *dst = *src; // fully opaque: plain overwrite
        return;
    }

    let inv_a = 255 - sa as u32;

    let r = src.red() as u32 + div255(dst.red() as u32 * inv_a);
    let g = src.green() as u32 + div255(dst.green() as u32 * inv_a);
    let b = src.blue() as u32 + div255(dst.blue() as u32 * inv_a);
    let a = (sa as u32 + div255(dst.alpha() as u32 * inv_a)).min(255);

    let r = r.min(a) as u8;
    let g = g.min(a) as u8;
    let b = b.min(a) as u8;
    let a = a as u8;

    *dst = unsafe { tiny_skia::PremultipliedColorU8::from_rgba(r, g, b, a).unwrap_unchecked() };
}
